mapper.select:
/*AdmGroupUserRelDAO.selectAdmGroupUserRel 어드민그룹사용자관계 정보 조회 */ SELECT GROUP_ID /* 그룹아이디 */ , USER_ID /* 사용자아이디 */ , USE_YN /* 사용여부 */ , FRST_REGI_USER_ID /* 최초등록사용자아이디 */ , FRST_REGI_TMSP /* 최초등록타임스탬프 */ , LAST_CHNG_USER_ID /* 최종변경사용자아이디 */ , LAST_CHNG_TMSP /* 최종변경타임스탬프 */ FROM ADM_GROUP_USER_REL WHERE 1=1
AND GROUP_ID = #{groupId} /* 그룹아이디 */
AND USER_ID = #{userId} /* 사용자아이디 */

mapper.insert:
/*AdmGroupUserRelDAO.insertAdmGroupUserRelHst 어드민그룹사용자관계 이력 등록*/
INSERT INTO ADM_GROUP_USER_REL_HST
SELECT *
FROM ADM_GROUP_USER_REL
WHERE GROUP_ID = #{groupId} AND USER_ID = #{userId}

mapper.update:
    	UPDATE ADM_GROUP_USER_REL
		SET USE_YN = 'N'
		     , LAST_CHNG_USER_ID = #{lastChngUserId}
			 , LAST_CHNG_TMSP = SYSTIMESTAMP
		 WHERE USER_ID = #{userId}

mapper.insert:
MERGE INTO ADM_GROUP_USER_REL R1 USING(
SELECT #{item.userId} AS userId , #{item.groupId} AS groupId , #{item.frstRegiUserId} AS frstRegiUserId , #{item.lastChngUserId} AS lastChngUserId FROM DUAL
) T1 ON (R1.USER_ID = T1.userId AND R1.GROUP_ID= T1.groupId) WHEN MATCHED THEN UPDATE SET R1.USE_YN = 'Y' , R1.LAST_CHNG_USER_ID = T1.lastChngUserId , R1.LAST_CHNG_TMSP = SYSTIMESTAMP WHERE R1.GROUP_ID = T1.groupId AND R1.USER_ID = T1.userId WHEN NOT MATCHED THEN INSERT ( USER_ID , USE_YN , GROUP_ID , FRST_REGI_USER_ID , FRST_REGI_TMSP ) VALUES ( T1.userId , 'Y' , T1.groupId , T1.frstRegiUserId , SYSTIMESTAMP )
